using System.Net;using System.Net.Http.Json;
namespace StockSyncAI.Tests.Api;
public sealed class InvoicePostingEndpointTests
{[Fact] public async Task PostingRoutes_RequireAuthenticationAndMalformedConfirmationIsRejected(){using var factory=new HealthEndpointTests.ApiFactory();using var client=factory.CreateClient();var invoice=Guid.NewGuid();var posting=Guid.NewGuid();Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync($"/api/invoices/{invoice}/posting")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsync($"/api/invoices/{invoice}/posting/prepare",null)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync($"/api/invoices/{invoice}/posting/{posting}/execute",new{confirmation="POST TO POS"})).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync($"/api/invoices/{invoice}/posting/history")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync($"/api/invoices/{invoice}/posting/{posting}/reconciliation/refresh",new{requestId=Guid.NewGuid()})).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync($"/api/invoices/{invoice}/posting/{posting}/reconciliation/decision",new{requestId=Guid.NewGuid(),decision="ReportedPosted",evidenceNote="observed"})).StatusCode);client.DefaultRequestHeaders.Add("X-StockSync-Token","test-secret-with-at-least-32-characters");Assert.Equal(HttpStatusCode.NotFound,(await client.GetAsync($"/api/invoices/{invoice}/posting")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await client.GetAsync($"/api/invoices/{invoice}/posting/history")).StatusCode);using var malformed=new StringContent("not-json",System.Text.Encoding.UTF8,"application/json");Assert.Equal(HttpStatusCode.BadRequest,(await client.PostAsync($"/api/invoices/{invoice}/posting/{posting}/execute",malformed)).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await client.PostAsJsonAsync($"/api/invoices/{invoice}/posting/{posting}/reconciliation/refresh",new{requestId=Guid.Empty})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await client.PostAsync($"/api/invoices/{invoice}/posting/{posting}/reconciliation/decision",new StringContent("not-json",System.Text.Encoding.UTF8,"application/json"))).StatusCode);}}
